content.title:
$files = Get-ChildItem -Recurse -File -Include *.md -ErrorAction SilentlyContinue
$rows = @()
foreach ($f in $files) {
  $base = [IO.Path]::GetFileNameWithoutExtension($f.Name).ToLowerInvariant() -replace '[^a-z0-9]+',' '
  $base = $base.Trim()
  $rows += [PSCustomObject]@{Key=$base; Path=$f.FullName.Substring((Get-Location).Path.Length + 1)}
}
$rows | Group-Object Key | Where-Object { $_.Count -gt 1 -and $_.Name -ne '' } | Sort-Object @{Expression='Count';Descending=$true}, @{Expression='Name';Descending=$false} | ForEach-Object { "### $($_.Name) ($($_.Count))"; $_.Group | ForEach-Object { "- $($_.Path)" } }

