content.title:
$root = (Get-Location).Path
$source = Join-Path $root 'Entities\Stocks\GOLD.md'
$target = Join-Path $root 'Entities\Stocks\Barrick Gold (GOLD).md'
$resolvedRoot = [System.IO.Path]::GetFullPath($root)
$resolvedSource = [System.IO.Path]::GetFullPath($source)
$resolvedTarget = [System.IO.Path]::GetFullPath($target)
if (-not $resolvedSource.StartsWith($resolvedRoot)) { throw "Source outside root: $resolvedSource" }
if (-not $resolvedTarget.StartsWith($resolvedRoot)) { throw "Target outside root: $resolvedTarget" }
if (-not (Test-Path -LiteralPath $resolvedSource)) { throw "Missing source: $resolvedSource" }
if (Test-Path -LiteralPath $resolvedTarget) { throw "Target already exists: $resolvedTarget" }
Move-Item -LiteralPath $resolvedSource -Destination $resolvedTarget

