content.title:
$encoding = New-Object System.Text.UTF8Encoding($false)
$files = Get-ChildItem -Recurse -File -Include *.md -ErrorAction SilentlyContinue
foreach ($file in $files) {
  $text = [System.IO.File]::ReadAllText($file.FullName)
  $updated = $text.Replace('[[Entities/Stocks/GOLD|GOLD]]', '[[Entities/Stocks/Barrick Gold (GOLD)|GOLD]]')
  $updated = $updated.Replace('[[Entities/Stocks/GOLD]]', '[[Entities/Stocks/Barrick Gold (GOLD)|GOLD]]')
  if ($updated -ne $text) { [System.IO.File]::WriteAllText($file.FullName, $updated, $encoding) }
}

